CREATE TABLE public.drive_sync_bindings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),folder_id text UNIQUE NOT NULL,scope text NOT NULL CHECK(scope IN ('house','player','master')),house_id text REFERENCES public.campaign_houses(id),player_id uuid REFERENCES public.campaign_players(id),owner_user_id uuid NOT NULL,confirmed_by uuid NOT NULL,privacy_reviewed boolean NOT NULL DEFAULT false,runtime_authorized boolean NOT NULL DEFAULT false,enabled boolean NOT NULL DEFAULT false,last_checked_at timestamptz,last_error text,lease_token uuid,lease_until timestamptz,CHECK((scope='house' AND house_id IS NOT NULL AND player_id IS NULL) OR (scope='player' AND player_id IS NOT NULL) OR (scope='master' AND house_id IS NULL AND player_id IS NULL)));
GRANT SELECT ON public.drive_sync_bindings TO authenticated; GRANT ALL ON public.drive_sync_bindings TO service_role;
ALTER TABLE public.drive_sync_bindings ENABLE ROW LEVEL SECURITY;
CREATE POLICY bindings_admin ON public.drive_sync_bindings FOR SELECT TO authenticated USING(public.is_campaign_admin());
CREATE TABLE public.drive_sync_files(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),binding_id uuid NOT NULL REFERENCES public.drive_sync_bindings(id),entity_type text NOT NULL CHECK(entity_type IN ('record','letter','reply')),entity_id uuid NOT NULL,file_id text NOT NULL,etag text,base_snapshot jsonb NOT NULL,remote_hash text NOT NULL,last_synced_at timestamptz NOT NULL DEFAULT now(),UNIQUE(binding_id,entity_type,entity_id),UNIQUE(binding_id,file_id));
GRANT SELECT ON public.drive_sync_files TO authenticated; GRANT ALL ON public.drive_sync_files TO service_role;
ALTER TABLE public.drive_sync_files ENABLE ROW LEVEL SECURITY;
CREATE POLICY syncfiles_admin ON public.drive_sync_files FOR SELECT TO authenticated USING(public.is_campaign_admin());
CREATE TABLE public.drive_sync_inbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),binding_id uuid NOT NULL REFERENCES public.drive_sync_bindings(id),file_id text NOT NULL,remote_hash text NOT NULL,etag text,site_snapshot jsonb,folder_snapshot jsonb NOT NULL,state text NOT NULL DEFAULT 'review' CHECK(state IN ('review','conflict','applied','rejected')),resolved_by uuid,resolved_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(binding_id,file_id,remote_hash));
GRANT SELECT ON public.drive_sync_inbox TO authenticated; GRANT ALL ON public.drive_sync_inbox TO service_role;
ALTER TABLE public.drive_sync_inbox ENABLE ROW LEVEL SECURITY;
CREATE POLICY inbox_admin ON public.drive_sync_inbox FOR SELECT TO authenticated USING(public.is_campaign_admin());
ALTER TABLE public.sync_outbox ADD COLUMN next_attempt_at timestamptz NOT NULL DEFAULT now();
CREATE FUNCTION public.claim_drive_binding(p_id uuid,p_token uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.drive_sync_bindings SET lease_token=p_token,lease_until=now()+interval '2 minutes' WHERE id=p_id AND enabled AND privacy_reviewed AND runtime_authorized AND (lease_until IS NULL OR lease_until<now()); RETURN FOUND; END $$;
REVOKE ALL ON FUNCTION public.claim_drive_binding(uuid,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.claim_drive_binding(uuid,uuid) TO service_role;
CREATE FUNCTION public.resolve_drive_import(p_id uuid,p_choice text,p_content text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i public.drive_sync_inbox;b public.drive_sync_bindings;r public.campaign_records;l public.campaign_letters;p public.campaign_players;doc jsonb; rid uuid; BEGIN IF NOT public.is_campaign_admin() THEN RAISE EXCEPTION 'Acesso restrito ao administrador'; END IF; SELECT * INTO i FROM public.drive_sync_inbox WHERE id=p_id FOR UPDATE; IF NOT FOUND OR i.state NOT IN ('review','conflict') THEN RAISE EXCEPTION 'Revisão já encerrada'; END IF; SELECT * INTO b FROM public.drive_sync_bindings WHERE id=i.binding_id; IF NOT b.enabled OR NOT b.privacy_reviewed OR NOT b.runtime_authorized THEN RAISE EXCEPTION 'Pasta não autorizada'; END IF; IF p_choice='reject' THEN UPDATE public.drive_sync_inbox SET state='rejected',resolved_by=auth.uid(),resolved_at=now() WHERE id=p_id; RETURN; END IF; IF p_choice NOT IN ('folder','site','merge') THEN RAISE EXCEPTION 'Escolha inválida'; END IF; doc=i.folder_snapshot; IF doc->>'entityType'='record' THEN SELECT * INTO r FROM public.campaign_records WHERE id=(doc->>'id')::uuid FOR UPDATE; IF FOUND THEN IF r.visibility='gm' OR NOT ((b.scope='house' AND r.visibility='house' AND r.house_id=b.house_id) OR (b.scope='player' AND r.visibility='player' AND r.player_id=b.player_id)) THEN RAISE EXCEPTION 'Escopo não autorizado'; END IF; IF i.site_snapshot IS NOT NULL AND r.version<>(i.site_snapshot->>'version')::integer THEN RAISE EXCEPTION 'Versão do site mudou; execute reconciliação novamente'; END IF; IF p_choice<>'site' THEN UPDATE public.campaign_records SET title=doc->>'title',content=CASE WHEN p_choice='merge' THEN p_content ELSE doc->>'content' END,version=version+1,updated_by=auth.uid(),updated_at=now(),sync_state='pending' WHERE id=r.id; END IF; ELSE IF p_choice='site' OR b.scope='master' OR doc->>'visibility'='gm' THEN RAISE EXCEPTION 'Importação não autorizada'; END IF; INSERT INTO public.campaign_records(id,house_id,player_id,visibility,kind,title,content,created_by,updated_by) VALUES((doc->>'id')::uuid,b.house_id,b.player_id,CASE WHEN b.scope='house' THEN 'house' ELSE 'player' END,doc->>'kind',doc->>'title',doc->>'content',auth.uid(),auth.uid()); END IF; ELSIF doc->>'entityType'='reply' THEN IF p_choice='site' THEN NULL; ELSE SELECT * INTO l FROM public.campaign_letters WHERE id=(doc->>'letterId')::uuid FOR UPDATE; SELECT * INTO p FROM public.campaign_players WHERE id=b.player_id AND user_id=b.owner_user_id; IF b.scope<>'player' OR p.id IS NULL OR l.id IS NULL OR NOT (l.recipient_player_id=p.id OR (l.recipient_player_id IS NULL AND EXISTS(SELECT 1 FROM public.house_memberships m WHERE m.player_id=p.id AND m.house_id=l.recipient_house_id))) THEN RAISE EXCEPTION 'Autor/destinatário não autorizado'; END IF; IF EXISTS(SELECT 1 FROM public.letter_replies WHERE id=(doc->>'id')::uuid) THEN RAISE EXCEPTION 'Respostas existentes são imutáveis; crie uma nova resposta'; END IF; INSERT INTO public.letter_replies(id,letter_id,author_user_id,author_player_id,author_name,house_id,recipient_user_id,content,idempotency_key) VALUES((doc->>'id')::uuid,l.id,p.user_id,p.id,p.name,l.recipient_house_id,l.sender_user_id,doc->>'content',(doc->>'id')::uuid) ON CONFLICT(author_user_id,idempotency_key) DO NOTHING; INSERT INTO public.letter_receipts(letter_id,user_id) VALUES(l.id,p.user_id) ON CONFLICT DO NOTHING; END IF; ELSE RAISE EXCEPTION 'Missivas recebidas são imutáveis; utilize resposta'; END IF; UPDATE public.drive_sync_inbox SET state='applied',resolved_by=auth.uid(),resolved_at=now() WHERE id=p_id; END $$;
REVOKE ALL ON FUNCTION public.resolve_drive_import(uuid,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.resolve_drive_import(uuid,text,text) TO authenticated;
COMMENT ON TABLE public.drive_sync_bindings IS 'Explicit admin-confirmed privacy-reviewed runtime-authorized mappings. Existing archive folder IDs never enable execution.';
ALTER PUBLICATION supabase_realtime ADD TABLE public.drive_sync_inbox,public.drive_sync_bindings;